#!/usr/bin/env python3
"""Exercise the regional decoder using generated bytes only.

This runner accepts no experiment input paths and reads no CT, mask, score,
checkpoint, or precomputed fixture payload. Its only data are the small arrays
and metadata constructed below. Run with --output-dir to retain the JSON result.
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
from pathlib import Path
from typing import Callable

import numpy as np

from regional_common import coordinate_roundtrip, decode_batch, pool_triplet


def synthetic_batch(dtype: str = "<u2") -> tuple[bytes, dict, dict, dict, np.ndarray]:
    """A 6x6 crop inside an 8x9 synthetic source canvas, with nonzero offsets."""
    source = np.array(
        [[1000 * y + 31 * x + 257 for x in range(9)] for y in range(8)],
        dtype=np.uint16,
    )
    case = {
        "id": "synthetic-only-6x6",
        "bbox_source_xywh": [2, 1, 6, 6],
        "native_bbox_yxhw": [1, 2, 6, 6],
    }
    contract = {
        "width": 9,
        "height": 8,
        "strip_offset": 64,
        "strip_bytes": 8 * 9 * 2,
        "object_total_bytes": 64 + 8 * 9 * 2 + 16,
        "dtype": dtype,
    }
    chunks = []
    rows = []
    for native_y in range(1, 7):
        chunk = source[native_y, 2:8].astype(np.dtype(dtype)).tobytes()
        source_start = 64 + 2 * (native_y * 9 + 2)
        rows.append({
            "native_y": native_y,
            "payload_offset": len(chunks) * 12,
            "payload_bytes": 12,
            "payload_sha256": hashlib.sha256(chunk).hexdigest(),
            "range_inclusive": [source_start, source_start + 11],
        })
        chunks.append(chunk)
    batch = {
        "case_id": case["id"],
        "native_x_start": 2,
        "native_crop_width": 6,
        "native_row_start": 1,
        "row_count": 6,
        "rows": rows,
    }
    return b"".join(chunks), batch, contract, case, source[1:7, 2:8].copy()


def require_array(actual: np.ndarray, expected: np.ndarray, dtype: str) -> None:
    assert isinstance(actual, np.ndarray), "Decoder result is not an array"
    assert actual.dtype == np.dtype(dtype), (actual.dtype, dtype)
    assert actual.flags.c_contiguous, "Result is not C-contiguous"
    assert actual.shape == expected.shape, (actual.shape, expected.shape)
    np.testing.assert_array_equal(actual, expected)


def expect_rejection(operation: Callable[[], object]) -> None:
    try:
        operation()
    except ValueError:
        return
    raise AssertionError("Malformed synthetic input was accepted")


def decode_positive(dtype: str, reverse_rows: bool = False) -> None:
    body, batch, contract, case, expected = synthetic_batch(dtype)
    if reverse_rows:
        batch["rows"].reverse()
    actual = decode_batch(body, batch, contract, case)
    require_array(actual, expected, "uint16")


def decode_partial_batch() -> None:
    body, batch, contract, case, expected = synthetic_batch()
    batch["native_row_start"] = 3
    batch["row_count"] = 2
    batch["rows"] = copy.deepcopy(batch["rows"][2:4])
    for row in batch["rows"]:
        row["payload_offset"] -= 24
    require_array(decode_batch(body[24:48], batch, contract, case), expected[2:4], "uint16")


def decode_negative(name: str) -> None:
    body, batch, contract, case, _ = synthetic_batch()
    rows = batch["rows"]
    if name == "body_hash_corruption":
        body = bytes([body[0] ^ 1]) + body[1:]
    elif name == "declared_hash_corruption":
        rows[0]["payload_sha256"] = "0" * 64
    elif name == "source_range_shifted":
        rows[0]["range_inclusive"] = [v + 2 for v in rows[0]["range_inclusive"]]
    elif name == "source_range_wrong_length":
        rows[0]["range_inclusive"][1] -= 1
    elif name == "duplicate_native_row":
        rows[1]["native_y"] = rows[0]["native_y"]
        rows[1]["range_inclusive"] = rows[0]["range_inclusive"].copy()
    elif name == "missing_native_row":
        rows.pop()
    elif name == "unexpected_native_row":
        rows[-1]["native_y"] += 1
    elif name == "overlapping_payload_intervals":
        # Both row hashes remain valid, isolating the overlap check.
        rows[1]["payload_offset"] = rows[0]["payload_offset"]
        rows[1]["payload_sha256"] = rows[0]["payload_sha256"]
    elif name == "truncated_body":
        body = body[:-1]
    elif name == "negative_payload_offset":
        rows[0]["payload_offset"] = -1
    elif name == "payload_offset_beyond_body":
        rows[-1]["payload_offset"] = len(body)
    elif name == "incorrect_payload_size":
        rows[0]["payload_bytes"] -= 2
    elif name == "invalid_native_endian":
        contract["dtype"] = "=u2"
    elif name == "invalid_byte_order_free_dtype":
        contract["dtype"] = "|u2"
    elif name == "invalid_sample_width":
        contract["dtype"] = "<u4"
    elif name == "crop_exceeds_source_width":
        contract["width"] = 7
    elif name == "crop_exceeds_source_height":
        contract["height"] = 6
    elif name == "coordinate_order_mismatch":
        case["native_bbox_yxhw"] = [2, 1, 6, 6]
    elif name == "batch_horizontal_crop_mismatch":
        batch["native_x_start"] += 1
    elif name == "batch_exceeds_crop":
        batch["native_row_start"] += 1
    elif name == "noninteger_row_count":
        batch["row_count"] = 6.0
    elif name == "noninteger_native_row":
        rows[0]["native_y"] = 1.0
    elif name == "strip_exceeds_object":
        contract["object_total_bytes"] = contract["strip_offset"] + contract["strip_bytes"] - 1
    elif name == "row_exceeds_strip":
        contract["strip_bytes"] = 12
    else:
        raise AssertionError(f"Unknown fixture {name}")
    expect_rejection(lambda: decode_batch(body, batch, contract, case))


def pooling_known_values() -> None:
    planes = np.array(
        [[[100 * z + 10 * y + x for x in range(6)] for y in range(6)] for z in range(3)],
        dtype=np.uint16,
    )
    # Literal sums for the four 3x3x3 blocks: mean is [111,114;141,144].
    # The input contract additionally rescales uint16 samples by 1/257.
    expected = (np.array([[2997, 3078], [3807, 3888]], dtype=np.float64) / 6939).astype(np.float32)
    require_array(pool_triplet(planes), expected, "float32")


def pooling_no_intermediate_rounding() -> None:
    planes = np.zeros((3, 3, 3), dtype=np.uint16)
    planes[2, 2, 2] = 1
    expected = np.array([[1.0 / 6939.0]], dtype=np.float32)
    require_array(pool_triplet(planes), expected, "float32")


def pooling_maximum_value() -> None:
    require_array(
        pool_triplet(np.full((3, 6, 6), 65535, dtype=np.uint16)),
        np.full((2, 2), 255.0, dtype=np.float32),
        "float32",
    )


def coordinate_known_values() -> None:
    _, _, _, case, _ = synthetic_batch()
    result = coordinate_roundtrip(case, shape=(2, 2))
    assert result["status"] == "PASS"
    assert result["coarse_centers_checked"] == 4
    assert result["first_source_center_yx"] == [2, 3]
    assert result["last_source_center_yx"] == [5, 6]
    assert result["released_mapping_compared"] is False


def coordinate_declared_mapping() -> None:
    _, _, _, case, _ = synthetic_batch()
    case["source_pixel_center_mapping"] = {"x": "2+1+3*x_coarse", "y": "1+1+3*y_coarse"}
    result = coordinate_roundtrip(case, shape=(2, 2))
    assert result["status"] == "PASS"
    assert result["released_mapping_compared"] is True
    assert result["mapping_x"] == case["source_pixel_center_mapping"]["x"]
    assert result["mapping_y"] == case["source_pixel_center_mapping"]["y"]


def coordinate_invalid_mapping(swapped: bool = False) -> None:
    _, _, _, case, _ = synthetic_batch()
    case["source_pixel_center_mapping"] = (
        {"x": "1+1+3*y_coarse", "y": "2+1+3*x_coarse"}
        if swapped else {"x": "3+1+3*x_coarse", "y": "1+1+3*y_coarse"}
    )
    expect_rejection(lambda: coordinate_roundtrip(case, shape=(2, 2)))


def run_fixtures() -> dict:
    fixtures: list[tuple[str, Callable[[], None]]] = [
        ("decode_little_endian_exact", lambda: decode_positive("<u2")),
        ("decode_big_endian_exact", lambda: decode_positive(">u2")),
        ("decode_unsorted_row_descriptors", lambda: decode_positive("<u2", reverse_rows=True)),
        ("decode_partial_batch", decode_partial_batch),
    ]
    negative_names = [
        "body_hash_corruption", "declared_hash_corruption", "source_range_shifted",
        "source_range_wrong_length", "duplicate_native_row", "missing_native_row",
        "unexpected_native_row", "overlapping_payload_intervals", "truncated_body",
        "negative_payload_offset", "payload_offset_beyond_body", "incorrect_payload_size",
        "invalid_native_endian", "invalid_byte_order_free_dtype", "invalid_sample_width",
        "crop_exceeds_source_width", "crop_exceeds_source_height", "coordinate_order_mismatch",
        "batch_horizontal_crop_mismatch", "batch_exceeds_crop", "noninteger_row_count",
        "noninteger_native_row", "strip_exceeds_object", "row_exceeds_strip",
    ]
    fixtures.extend((f"reject_{name}", lambda name=name: decode_negative(name)) for name in negative_names)
    fixtures.extend([
        ("pool_known_3x3x3_sums", pooling_known_values),
        ("pool_preserves_fractional_mean", pooling_no_intermediate_rounding),
        ("pool_maximum_uint16_without_overflow", pooling_maximum_value),
        ("reject_pool_wrong_plane_count", lambda: expect_rejection(
            lambda: pool_triplet(np.zeros((2, 6, 6), dtype=np.uint16)))),
        ("reject_pool_height_not_divisible_by_three", lambda: expect_rejection(
            lambda: pool_triplet(np.zeros((3, 5, 6), dtype=np.uint16)))),
        ("reject_pool_width_not_divisible_by_three", lambda: expect_rejection(
            lambda: pool_triplet(np.zeros((3, 6, 5), dtype=np.uint16)))),
        ("reject_pool_values_beyond_uint16", lambda: expect_rejection(
            lambda: pool_triplet(np.full((3, 3, 3), 65536, dtype=np.uint32)))),
        ("coordinate_roundtrip_known_centers", coordinate_known_values),
        ("coordinate_roundtrip_declared_mapping", coordinate_declared_mapping),
        ("reject_coordinate_mapping_mutated_x", coordinate_invalid_mapping),
        ("reject_coordinate_mapping_swapped_axes", lambda: coordinate_invalid_mapping(swapped=True)),
    ])
    results = []
    for name, operation in fixtures:
        try:
            operation()
        except Exception as error:
            results.append({"name": name, "status": "FAIL", "error_type": type(error).__name__, "error": str(error)})
        else:
            results.append({"name": name, "status": "PASS"})
    failed = sum(result["status"] == "FAIL" for result in results)
    return {
        "schema": "regional-synthetic-fixtures-v1",
        "status": "FAIL" if failed else "PASS",
        "synthetic_only": True,
        "experiment_payloads_read": False,
        "checkpoint_loaded": False,
        "source_canvas_shape_yx": [8, 9],
        "crop_shape_yx": [6, 6],
        "total": len(results),
        "passed": len(results) - failed,
        "failed": failed,
        "fixtures": results,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir", type=Path, required=True, help="Directory for synthetic-fixtures.json")
    args = parser.parse_args()
    args.output_dir.mkdir(parents=True, exist_ok=True)
    output_path = args.output_dir / "synthetic-fixtures.json"
    # Refuse to overwrite a retained check from a previous run.
    with output_path.open("x", encoding="utf-8") as handle:
        report = run_fixtures()
        json.dump(report, handle, indent=2, sort_keys=True, allow_nan=False)
        handle.write("\n")
    print(json.dumps({"status": report["status"], "passed": report["passed"],
                      "failed": report["failed"], "report": str(output_path.resolve())}))
    return 1 if report["failed"] else 0


if __name__ == "__main__":
    raise SystemExit(main())
